(window.LADDER_CARDS=window.LADDER_CARDS||{})["32a"]=[{"q": "f(x + 2π) = f(x) for every x. What is f called on the page?", "a": "periodic, with period 2π", "w": ["even, with period 2π", "a turning of speed 2π", "a coefficient of speed 2π"], "why": "A function that repeats every 2π is periodic, with period 2π."}, {"q": "What is the nth turning on this rung?", "a": "eₙ(x) = e^(inx)", "w": ["eₙ(x) = cos(nx)", "eₙ(x) = e^(nx)", "eₙ(x) = xⁿ"], "why": "The turning runs n times round the circle of size 1 as x runs once along [−π, π]."}, {"q": "A line reads ⟨e₃, e₅⟩ = 0. Which technique licenses it?", "a": "right-angled-turnings", "w": ["turning-shadow", "cosine-and-sine", "power-to-sum"], "why": "Any two different turnings are at right angles."}, {"q": "What is ⟨e₄, e₄⟩, with the weight 1/2π?", "a": "1", "w": ["0", "2π", "4"], "why": "Every turning has size 1: (1/2π)∫ 1 dx over [−π, π] is 1."}, {"q": "cₙ = (1/2π)∫ f(x)e^(−inx) dx over [−π, π]. What is cₙ called?", "a": "the nth coefficient (Fourier coefficient)", "w": ["the nth partial sum (Fourier partial sum)", "the nth turning of f", "the energy of f"], "why": "The coefficient is the shadow of f on the nth turning."}, {"q": "S_N f = Σ cₙeₙ over |n| ≤ N. What is it called?", "a": "the Nth partial sum (Fourier partial sum)", "w": ["the Nth coefficient (Fourier coefficient)", "the Nth blend", "the Nth energy"], "why": "The closest sum of the turnings from −N to N."}, {"q": "A fit of turnings from −N to N adds e_(N+1). What happens to c₀, …, c_N?", "a": "nothing: each is fixed once found", "w": ["each shrinks a little", "each must be found again", "c₀ alone changes"], "why": "The turning-shadow technique: a shadow on right-angled turnings names no N."}, {"q": "f is even on [−π, π]. Which coefficients bₙ of its sines are 0?", "a": "all of them", "w": ["none of them", "the even ones", "the odd ones"], "why": "Cosine-and-sine: f sin nx is odd and totals 0."}, {"q": "A line reads c₋ₙ = c̄ₙ. What makes it true?", "a": "f is real", "w": ["f is even", "f is odd", "f repeats every 2π"], "why": "For a real f the flip passes onto e^(−inx)."}, {"q": "cos x and sin x cross at π/4. Are they at right angles in this product?", "a": "yes: their product totals 0 over a turn", "w": ["no: they cross at π/4", "no: they are the same wave slid", "only on [0, π/2]"], "why": "Right angles here are a total of the product, not where graphs cross."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32b"]=[{"q": "A line reads Σ|cₙ|² ≤ ‖f‖². Which technique licenses it?", "a": "fading-coefficients", "w": ["energy-kept", "turnings-near-everything", "turning-shadow"], "why": "The energy bound for a right-angled list (31h2), read for the turnings."}, {"q": "A line reads cₙ → 0 for f of finite energy. Why?", "a": "the terms of a settling sum head to 0", "w": ["f is continuous", "f has a slope", "the turnings are bounded"], "why": "Σ|cₙ|² settles under ‖f‖², so its terms fade."}, {"q": "Every continuous wave that repeats every 2π is within ε of a finite sum of turnings at every x at once. Which technique?", "a": "turnings-near-everything", "w": ["energy-kept", "fading-coefficients", "averaged-sums"], "why": "The average-polynomial technique, bent by x ↦ cos x."}, {"q": "A line reads ‖f‖² = Σ|cₙ|² over every n. Which technique licenses it?", "a": "energy-kept", "w": ["fading-coefficients", "transform-energy", "energy-bound"], "why": "The turnings leave no direction out, so the bound is an equality."}, {"q": "f is x on (−π, π), repeated. What is it called?", "a": "the sawtooth", "w": ["the square wave", "the triangle", "the bell"], "why": "It climbs steadily and drops at every odd multiple of π."}, {"q": "The sawtooth has cₙ = i(−1)ⁿ/n. What is |cₙ|²?", "a": "1/n²", "w": ["1/n", "(−1)ⁿ/n²", "i/n²"], "why": "The size of i(−1)ⁿ is 1."}, {"q": "π²/3 = 2(1 + ¼ + ⅑ + ⋯). What is 1 + ¼ + ⅑ + ⋯?", "a": "π²/6", "w": ["π²/3", "π/4", "2"], "why": "Energy-kept on the sawtooth counts n and −n; each side gives π²/6."}, {"q": "A line reads ‖f − S_N f‖ → 0, so S_N f(x) → f(x) at every x. Is the move allowed?", "a": "no: nearness in size is an average", "w": ["yes: by energy-kept", "yes: by fading-coefficients", "only for even f"], "why": "An average can hide misses at points."}, {"q": "Every coefficient of f is 0. What does 32b give?", "a": "f is 0 but for a set of size zero", "w": ["f is 0 at every point", "f is a constant", "nothing about f"], "why": "Its energy is Σ|cₙ|² = 0."}, {"q": "A sum of microphone shares falls short of the recording’s energy. Where does the energy-kept technique place the error?", "a": "in the measurement", "w": ["in the splitting into turnings", "in the turnings that were missed", "in rounding the totals"], "why": "The ledger: splitting loses no energy and makes none."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32c"]=[{"q": "S_N f(x) = (1/2π)∫ f(x − s)D_N(s) ds. Which technique gives it?", "a": "turning-kernel", "w": ["slope-returns", "blend-coefficients", "halfway"], "why": "The coefficient totals put inside the partial sum."}, {"q": "D_N(s) = sin((N + ½)s)/sin(s/2). What is its average over a repeat?", "a": "1", "w": ["0", "2N + 1", "N"], "why": "Only the turning n = 0 has a total."}, {"q": "f has a slope at x. What does S_N f(x) do?", "a": "settles at f(x)", "w": ["settles halfway", "overshoots by nine per cent", "may wander"], "why": "The slope-returns technique."}, {"q": "f jumps at x from f(x⁻) to f(x⁺), with a slope on each side. Where do the sums settle?", "a": "at (f(x⁻) + f(x⁺))/2", "w": ["at f(x⁻)", "at f(x⁺)", "at f(x)"], "why": "The halfway technique: the value at the jump changes no total."}, {"q": "The square wave’s sums rise near the jump to about 1.179, for every number of turnings. Which technique?", "a": "lasting-overshoot", "w": ["slope-returns", "halfway", "averaged-sums"], "why": "The peak heads to (2/π) times the total of sin t / t from 0 to π."}, {"q": "About how much of the jump does the overshoot pass the top by?", "a": "about nine per cent", "w": ["about one per cent", "about half", "nothing in the limit"], "why": "0.179 out of a jump of 2."}, {"q": "f is continuous at x, so S_N f(x) → f(x). Is the move allowed?", "a": "no: the proof needs a slope or a bound C|s|", "w": ["yes: by slope-returns", "yes: by kept-continuity", "only when f is even"], "why": "Some continuous wave has partial sums that wander at a point."}, {"q": "|f(x − s) − f(x)| ≤ C|s| near x, but no slope at x. Do the sums return f(x)?", "a": "yes: the proof needs only that bound", "w": ["no: a slope is required", "only halfway", "only on average"], "why": "The bound keeps the leftover’s weight bounded."}, {"q": "The sawtooth at its jump at π: what do its sums give?", "a": "0", "w": ["π", "−π", "π/2"], "why": "The halfway point between π and −π."}, {"q": "The sums settle at every point, so they come near f everywhere at once. Is the move allowed for the square wave?", "a": "no: a jump forbids it", "w": ["yes: settling at each point is enough", "yes: by the halfway technique", "only far from the jump"], "why": "A limit everywhere at once of continuous sums is continuous (23d)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32d"]=[{"q": "(f * g)(x) = (1/2π)∫ f(x − t)g(t) dt. What is f * g called?", "a": "the blend of f by g (convolution)", "w": ["the product of f and g", "the shadow of f on g", "the transform of f"], "why": "At each x it is an average of f near x weighted by g."}, {"q": "A line reads cₙ(f * g) = cₙ(f)cₙ(g). Which technique licenses it?", "a": "blend-coefficients", "w": ["blend-smooths", "turning-shadow", "averaged-sums"], "why": "Either order (30e), with the turning split as e^(−in(x−t))e^(−int)."}, {"q": "A line reads cₙ(fg) = cₙ(f)cₙ(g). Is the move allowed?", "a": "no: it is the blend that multiplies coefficients", "w": ["yes: by blend-coefficients", "yes: when f and g are bounded", "only for n = 0"], "why": "A product of functions moves speeds."}, {"q": "g has a continuous slope, f is only bounded. How smooth is f * g?", "a": "it has a slope, (f * g)′ = f * g′", "w": ["as rough as f", "continuous only", "it has no slope at f’s jumps"], "why": "Blend-smooths: the blend takes on the smoother function’s slope."}, {"q": "What does a blend do to the turning eₙ?", "a": "scales it by cₙ(g)", "w": ["moves it to speed 2n", "leaves it unchanged", "slides it by n"], "why": "eₙ * g = cₙ(g)eₙ."}, {"q": "σ_N f = (S₀f + ⋯ + S_(N−1)f)/N. What is it?", "a": "the average of the first N partial sums", "w": ["the Nth partial sum", "the Nth coefficient", "the blend of f with D_N"], "why": "It is the blend of f with F_N."}, {"q": "For every continuous f repeating every 2π, σ_N f comes near f everywhere at once. Which technique?", "a": "averaged-sums", "w": ["slope-returns", "turnings-near-everything", "blend-smooths"], "why": "F_N is never negative, has average 1 and gathers at 0."}, {"q": "Which property does F_N have that D_N lacks?", "a": "it is never negative", "w": ["its average is 1", "it is a sum of turnings", "it is even"], "why": "D_N swings below 0, and that is where 32c’s trouble comes from."}, {"q": "σ_N f → f at once, so S_N f → f at once. Is the move allowed?", "a": "no: the averages can settle where the sums do not", "w": ["yes: averages of settling sums settle", "yes: by blend-coefficients", "only for even f"], "why": "The square wave’s sums overshoot, its averages do not."}, {"q": "The weight π/h on [−h, h]: what is cₙ of it, for n ≠ 0?", "a": "sin(nh)/(nh)", "w": ["cos(nh)", "1/(nh)", "π/h"], "why": "(1/2π)∫ from −h to h of (π/h)e^(−int) dt."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32e"]=[{"q": "f̂(ξ) = ∫ f(x)e^(−2πixξ) dx over the line. What is f̂ called?", "a": "the transform of f (Fourier transform)", "w": ["the blend of f (convolution)", "the nth coefficient of f", "the energy of f"], "why": "What 32a’s coefficients become as the repeat grows without end."}, {"q": "f has a finite total size. A line reads |f̂(ξ)| ≤ ∫|f|. Which technique?", "a": "transform-bound", "w": ["own-transform", "transform-energy", "undo-transform"], "why": "The size of a total is at most the total of the size."}, {"q": "What is the transform of the box 1 on [−½, ½]?", "a": "sin(πξ)/(πξ)", "w": ["the box again", "e^(−πξ²)", "1/(1 + ξ²)"], "why": "The total of e^(−2πixξ) from −½ to ½."}, {"q": "A line reads ĝ = g for g(x) = e^(−πx²). Which technique licenses it?", "a": "own-transform", "w": ["bell-total", "undo-transform", "transform-bound"], "why": "Both obey y′ = −2πξy with y(0) = 1."}, {"q": "f(x) = ∫ f̂(ξ)e^(2πixξ) dξ at every x where f is continuous. Which technique?", "a": "undo-transform", "w": ["own-transform", "transform-energy", "turning-shadow"], "why": "The turning runs forwards to undo what it did backwards."}, {"q": "∫|f̂|² = ∫|f|² over the line. Which technique?", "a": "transform-energy", "w": ["energy-kept", "transform-bound", "fading-coefficients"], "why": "The energy-kept technique with every frequency allowed."}, {"q": "The box has a finite total. Does its transform?", "a": "no: sin(πξ)/(πξ) fades only like 1/ξ", "w": ["yes: by transform-bound", "yes: it is bounded", "yes: it is continuous"], "why": "Bounded and continuous is not the same as a finite total."}, {"q": "A narrower bell has a narrower transform. Is the move allowed?", "a": "no: stretching one squeezes the other", "w": ["yes: by own-transform", "yes: bells keep their width", "only for the bell of width 1"], "why": "e^(−πx²/s²) has transform s e^(−πs²ξ²)."}, {"q": "What is the transform of a blend on the line?", "a": "the product of the transforms", "w": ["the sum of the transforms", "the blend of the transforms", "the transform of the product"], "why": "The blend-coefficients proof runs unchanged on the line."}, {"q": "The undo-transform proof puts e^(−πε²ξ²) inside the total. Why?", "a": "to make the total on the plane finite, so the order can swap", "w": ["to make f continuous", "to make f̂ a bell", "to shrink the energy"], "why": "Either order needs a finite total; then ε heads to 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32f"]=[{"q": "A line reads the transform of f′ is 2πiξ f̂(ξ). Which technique?", "a": "slope-to-frequency", "w": ["spread-product", "undo-transform", "corner-and-jump"], "why": "Parts, with the ends vanishing."}, {"q": "Δx Δξ ≥ 1/(4π) for every signal of energy 1 with xf and f′ of finite energy. What is its accepted name?", "a": "the spread-product technique (the uncertainty principle)", "w": ["the tightest-bell technique (the uncertainty principle)", "the transform-energy technique (the uncertainty principle)", "the energy-kept technique (the uncertainty principle)"], "why": "The page names the spread-product technique the uncertainty principle."}, {"q": "Which earlier bound does the spread-product proof spend on xf and f′?", "a": "product-bound", "w": ["energy-bound", "transform-bound", "product-triangle"], "why": "|⟨xf, f′⟩| ≤ ‖xf‖ ‖f′‖."}, {"q": "Which signals have Δx Δξ exactly 1/(4π)?", "a": "the bells, A e^(−cx²) with c > 0", "w": ["the boxes", "the turnings", "every even signal"], "why": "Tightest-bell: equality forces f′ = −λxf."}, {"q": "A tone has a width of 0.01 s in time. About how wide is it at least in frequency?", "a": "about 8 Hz", "w": ["about 0.08 Hz", "about 100 Hz", "about 0.8 Hz"], "why": "1/(4π × 0.01) ≈ 7.96."}, {"q": "A better instrument beats 1/(4π). Is the move allowed?", "a": "no: the bound is about the signal", "w": ["yes: with finer readings", "yes: for short pulses", "only for bells"], "why": "The proof uses only f and its transform."}, {"q": "The box 1 on [−½, ½]: what is its width in frequency?", "a": "endless", "w": ["1/(4π)", "1/(2√π)", "1"], "why": "Its transform fades like 1/ξ, so ξ²|f̂|² does not fade."}, {"q": "For f = 2^(1/4)e^(−πx²), what is Δx?", "a": "1/(2√π)", "w": ["1/(4π)", "1", "√π"], "why": "Δx² = 1/(4π), and Δξ is the same since f̂ = f."}, {"q": "A slope in time becomes what in frequency?", "a": "a multiplication by 2πiξ", "w": ["a slope in ξ", "a division by ξ", "a slide by ξ"], "why": "Slope-to-frequency."}, {"q": "A radar pulse fixes a boat’s place well. What does the cloud say about its speed?", "a": "it is read less sharply", "w": ["it is read more sharply", "it is unaffected", "it cannot be read at all"], "why": "A short pulse is wide in frequency."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32g"]=[{"q": "f(x) = ∫ from −B to B of F(ξ)e^(2πixξ) dξ, with F of finite energy. What is f called?", "a": "a band-limited signal, with band B", "w": ["a periodic signal, with period B", "a sampled signal, with rate B", "a blend, with weight B"], "why": "No frequency above B."}, {"q": "A line reads cₙ(F) = f(−n/(2B))/(2B). Which technique?", "a": "samples-are-coefficients", "w": ["sample-rebuild", "same-samples", "turning-shadow"], "why": "The samples are the coefficients of the transform on [−B, B]."}, {"q": "f(x) = Σ f(k/(2B)) sinc(2Bx − k). Which technique?", "a": "sample-rebuild", "w": ["samples-are-coefficients", "undo-transform", "same-samples"], "why": "Each sample times a fading wave centred on its instant."}, {"q": "What is sinc(3), with sinc(u) = sin(πu)/(πu)?", "a": "0", "w": ["1", "1/(3π)", "−1"], "why": "sin(3π) = 0: sinc is 0 at every whole number but 0."}, {"q": "A signal has no frequency above 5000 Hz. What spacing of samples suffices?", "a": "1/10 000 s", "w": ["1/5000 s", "1/2500 s", "1/20 000 s"], "why": "Twice the top frequency: 1/(2B)."}, {"q": "Sampled at r = 44 100, a 30 000 Hz tone is read as what?", "a": "a 14 100 Hz tone", "w": ["a 30 000 Hz tone", "silence", "a 74 100 Hz tone"], "why": "Same-samples: 30 000 − 44 100 = −14 100."}, {"q": "Sampling at the rate B is enough for a signal with no frequency above B. Is the move allowed?", "a": "no: the rate must be 2B", "w": ["yes: by sample-rebuild", "yes: one sample per turn", "only for even signals"], "why": "Frequencies ξ and ξ − B share the samples."}, {"q": "Why is a sound filtered before it is sampled?", "a": "frequencies above half the rate come back as false low ones", "w": ["the samples would be too large", "the transform would not exist", "the energy would be lost"], "why": "They are not lost; they disguise themselves."}, {"q": "Between the samples the rebuilt wave is a straight line. Is the move allowed?", "a": "no: it is a sum of fading waves", "w": ["yes: the samples are joined", "yes: by samples-are-coefficients", "only at twice the rate"], "why": "Every sample has its say between the instants."}, {"q": "A compact disc samples at 44 100 per second. What is the top frequency it holds?", "a": "22 050 Hz", "w": ["44 100 Hz", "20 000 Hz", "11 025 Hz"], "why": "Half the rate."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32h"]=[{"q": "(4/π)(sin x + sin 3x/3 + sin 5x/5 + ⋯). Which wave is it?", "a": "the square wave", "w": ["the sawtooth", "the triangle", "the bell"], "why": "Square-recipe: the odd speeds alone, each over its speed."}, {"q": "The square recipe read at x = π/2 gives which sum?", "a": "1 − 1/3 + 1/5 − ⋯ = π/4", "w": ["1 + 1/9 + 1/25 + ⋯ = π²/8", "1 + ¼ + ⅑ + ⋯ = π²/6", "1 − ½ + ⅓ − ⋯"], "why": "sin(nπ/2) is 1, 0, −1, 0, …"}, {"q": "The square wave’s energy, by energy-kept, gives which sum?", "a": "1 + 1/9 + 1/25 + ⋯ = π²/8", "w": ["1 − 1/3 + 1/5 − ⋯ = π/4", "1 + ¼ + ⅑ + ⋯ = π²/6", "1 + 1/16 + ⋯ = π⁴/90"], "why": "1 = (8/π²)(1 + 1/9 + ⋯)."}, {"q": "A wave is slid by s. What happens to its nth coefficient?", "a": "it is multiplied by e^(−ins)", "w": ["it is multiplied by s", "it is unchanged", "it moves to speed n + s"], "why": "Slide-and-stretch: a slide is a turn of size 1."}, {"q": "A constant k is added to a wave. Which coefficients change?", "a": "c₀ alone", "w": ["every cₙ", "none", "the odd ones"], "why": "The constant is the 0th turning."}, {"q": "A line reads cₙ(f′) = in cₙ(f). Which technique?", "a": "corner-and-jump", "w": ["slope-to-frequency", "slide-and-stretch", "rate-to-algebra"], "why": "Parts, with the end terms cancelling for a continuous repeating f."}, {"q": "A wave jumps. How fast do its amounts fall?", "a": "like 1/n", "w": ["like 1/n²", "like 1/n³", "they do not fall"], "why": "The square and the sawtooth."}, {"q": "The triangle |x| has corners and no jump. How fast do its amounts fall?", "a": "like 1/n²", "w": ["like 1/n", "like 1/√n", "like 2⁻ⁿ"], "why": "Its slope is the square wave."}, {"q": "Sliding a wave changes the sizes |cₙ|. Is the move allowed?", "a": "no: a slide multiplies by a turn of size 1", "w": ["yes: the shape moves", "yes: by slide-and-stretch", "only for odd n"], "why": "Only the turns of the coefficients change."}, {"q": "q(0) = 1 for the square recipe. Is the move allowed?", "a": "no: at the jump it gives 0", "w": ["yes: q is 1 just right of 0", "yes: by slope-returns", "only in the limit"], "why": "Halfway between −1 and 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32i"]=[{"q": "The kth entry is a₀b_k + a₁b_(k−1) + ⋯ + a_kb₀. What is the list called?", "a": "the blend of the two lists", "w": ["the product of the two lists", "the transform of the two lists", "the sum of the two lists"], "why": "Every pairing whose places add to k."}, {"q": "Two dice: what is the chance of a total of 7?", "a": "6/36", "w": ["1/36", "7/36", "1/12"], "why": "List-blend: the tent (1, 2, …, 6, …, 1)/36."}, {"q": "Chances of X + Y for independent counts are the blend of their chance lists. Which technique?", "a": "list-blend", "w": ["gain-per-turning", "blend-coefficients", "sums-multiply"], "why": "Coefficients of a product of chance functions."}, {"q": "A blend multiplies each turning by H(n). What is |H(n)| called?", "a": "the gain at speed n", "w": ["the shift at speed n", "the energy at speed n", "the weight at speed n"], "why": "Gain-per-turning: the turn of H(n) is the shift."}, {"q": "The average over [x − π/3, x + π/3]: what is H(3)?", "a": "0", "w": ["1", "0.827", "1/3"], "why": "The window holds a whole wave of speed 3."}, {"q": "yₖ = (1 − β)y_(k−1) + β xₖ. What is H(ω)?", "a": "β/(1 − (1 − β)e^(−iω))", "w": ["β e^(−iω)", "(1 − β)/(1 − βe^(−iω))", "1/(1 − e^(−iω))"], "why": "Stepped-filter: a geometric sum of the old readings."}, {"q": "The running filter with β = 0.1 at ω = 0: what is H?", "a": "1", "w": ["0.1", "0.9", "0.053"], "why": "A steady reading shows unchanged."}, {"q": "P(X + Y = k) = P(X = k)P(Y = k). Is the move allowed?", "a": "no: every pairing j and k − j counts", "w": ["yes: X and Y are independent", "yes: by list-blend", "only for k = 0"], "why": "The blend adds over pairings."}, {"q": "A blend changes a turning into another speed. Is the move allowed?", "a": "no: each turning goes to a multiple of itself", "w": ["yes: high speeds move down", "yes: by gain-per-turning", "only for averages"], "why": "eₙ * g = cₙ(g)eₙ."}, {"q": "The running filter forgets old readings after a while. Is the move allowed?", "a": "no: each keeps a share β(1 − β)ʲ, never 0", "w": ["yes: after 1/β readings", "yes: by stepped-filter", "only when β is small"], "why": "Shares shrink but never reach 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32j"]=[{"q": "A repeating solution of y″ + by′ + cy = f has cₙ(y) = cₙ(f)/(c − n² + ibn). Which technique?", "a": "rate-to-algebra", "w": ["driven-response", "transfer", "corner-and-jump"], "why": "Each slope multiplies cₙ by in."}, {"q": "What is cₙ(y″) in terms of cₙ(y)?", "a": "−n²cₙ(y)", "w": ["n²cₙ(y)", "in cₙ(y)", "−in cₙ(y)"], "why": "(in)² = −n²."}, {"q": "When can the division of rate-to-algebra fail?", "a": "b = 0 and c = n² for a whole n", "w": ["b > 0 and c < 0", "c = 0", "f has a jump"], "why": "Then c − n² + ibn is 0."}, {"q": "A braked spring answers each speed n of the push scaled by 1/√((ω₀² − n²)² + 4β²n²). Which technique?", "a": "driven-response", "w": ["rate-to-algebra", "transfer", "gain-per-turning"], "why": "The size of the bottom, speed by speed."}, {"q": "A square push, a spring with ω₀ = 3.02 and a light brake. At which speed does it swing most?", "a": "speed 3", "w": ["speed 1", "speed 5", "every speed alike"], "why": "The bottom is smallest near ω₀."}, {"q": "y′ + ky = f, k > 0, gives ŷ = f̂/(k + 2πiξ). Which technique?", "a": "transfer", "w": ["rate-to-algebra", "slope-to-frequency", "driven-response"], "why": "A slope is a multiplication by 2πiξ."}, {"q": "H(ξ) = 1/(k + 2πiξ). What is H called?", "a": "the transfer function", "w": ["the transform", "the gain at k", "the kernel"], "why": "The number every frequency of the input is multiplied by."}, {"q": "An RC circuit with k = 1000 per second. Which tones does it pass?", "a": "low ones", "w": ["high ones", "every tone alike", "only 1000 Hz"], "why": "Its gain is about 0.954 at 50 Hz and 0.157 at 1000 Hz."}, {"q": "Every solution of y″ + 2βy′ + ω₀²y = f repeats. Is the move allowed?", "a": "no: the others add a decaying turn", "w": ["yes: f repeats", "yes: by rate-to-algebra", "only when β = 0"], "why": "Only one solution repeats."}, {"q": "The spring swings most at the push’s largest speed. Is the move allowed?", "a": "no: each speed is divided by its own number", "w": ["yes: the largest amount wins", "yes: by driven-response", "only without a brake"], "why": "Near ω₀ the number is small."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32k"]=[{"q": "X_k = Σ x_j ω^(−jk), ω = e^(2πi/N). What is X called?", "a": "the stepped transform of the list", "w": ["the blend of the list", "the coefficient of the list", "the energy of the list"], "why": "One number for each of N frequencies."}, {"q": "x_j = (1/N)Σ X_k ω^(jk). Which technique?", "a": "sampled-turnings", "w": ["halving-transform", "undo-transform", "turning-shadow"], "why": "The N stepped turnings are at right angles on N points."}, {"q": "What is the stepped transform of (1, 2, 3, 4)?", "a": "(10, −2 + 2i, −2, −2 − 2i)", "w": ["(10, 2 − 2i, 2, 2 + 2i)", "(10, −2, −2, −2)", "(4, 3, 2, 1)"], "why": "With ω = i."}, {"q": "X_k = E_k + ω^(−k)O_k and X_(k+M) = E_k − ω^(−k)O_k. Which technique?", "a": "halving-transform", "w": ["sampled-turnings", "list-blend", "unrolling"], "why": "Even places and odd places, reused for the second half."}, {"q": "Why does the second half reuse E and O?", "a": "they repeat every M, and ω^M = −1", "w": ["they are 0 there", "the list is even", "N is odd"], "why": "So no new transforms are needed."}, {"q": "On N = 2ᵖ points, about how many steps does the halving way take?", "a": "N log₂ N", "w": ["N²", "N", "2ᴺ"], "why": "T(N) = 2T(N/2) + N, unrolled."}, {"q": "For N = 1024, about how many steps does the plain way take?", "a": "about a million", "w": ["about ten thousand", "about a thousand", "about a billion"], "why": "N² = 1 048 576."}, {"q": "Music needs more than how many samples a second?", "a": "40 000", "w": ["20 000", "44 100", "22 050"], "why": "Twice the top of hearing."}, {"q": "44 100 = 3 × 245 × 60 = 3 × 294 × 50. What set this number?", "a": "three samples on each usable line of video", "w": ["the top of hearing", "the halving way", "the filter’s band"], "why": "Early digital sound was stored on video tape."}, {"q": "The halving way gives a different answer from the plain way. Is the move allowed?", "a": "no: the same sums, grouped", "w": ["yes: it rounds the turnings", "yes: it drops the odd places", "only when N is not a power of 2"], "why": "Only the cost changes."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32l"]=[{"q": "I(λ) = ∫ g(x)e^(iλφ(x)) dx. What is φ called?", "a": "the phase", "w": ["the weight", "the speed", "the level point"], "why": "The total is an oscillating total with phase φ."}, {"q": "φ′(x₀) = 0. What is x₀ called?", "a": "a level point of the phase", "w": ["a corner of the phase", "a root of the phase", "a jump of the phase"], "why": "The turning pauses there."}, {"q": "φ has no level point on [u, v]. A line reads |I(λ)| ≤ C/λ. Which technique?", "a": "no-level-point", "w": ["level-point", "turning-bell", "corner-and-jump"], "why": "Parts puts 1/λ in front."}, {"q": "A line reads ∫ e^(iλx²) dx = √(π/λ)e^(iπ/4). Which technique?", "a": "turning-bell", "w": ["own-transform", "bell-total", "level-point"], "why": "The bell’s total slid round a wedge."}, {"q": "Does ∫ from 0 to ∞ of e^(ix²) dx settle absolutely?", "a": "no: it settles by cancelling alone", "w": ["yes: the terms fade", "yes: by turning-bell", "yes: by bell-total"], "why": "Every term has size 1."}, {"q": "One level point with φ″ ≠ 0. How does I(λ) shrink?", "a": "like 1/√λ", "w": ["like 1/λ", "like 1/λ²", "it does not shrink"], "why": "Level-point: near the pause the phase is a square."}, {"q": "Away from the level points, how large is the total?", "a": "O(1/λ)", "w": ["O(1/√λ)", "O(1)", "O(λ)"], "why": "No-level-point on each piece."}, {"q": "The drum’s J(λ) for large λ is about which?", "a": "√(2/(πλ)) cos(λ − π/4)", "w": ["√(2/(πλ)) cos λ", "1/λ", "e^(−λ)"], "why": "Two level points, at t = 0 and t = π."}, {"q": "The turn e^(±iπ/4) can be dropped. Is the move allowed?", "a": "no: it shifts the drum’s ring by an eighth of a turn", "w": ["yes: it has size 1", "yes: it cancels between level points", "only for large λ"], "why": "It is measured in the ring."}, {"q": "The whole interval contributes equally to an oscillating total. Is the move allowed?", "a": "no: away from level points it is O(1/λ)", "w": ["yes: every term has size 1", "yes: by no-level-point", "only when g is constant"], "why": "The bulk lives near the pauses."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32·then"]=[{"q": "A turning of frequency ν₀ dies away over a life τ. What is its width at half height?", "a": "1/(2πτ)", "w": ["1/τ", "2πτ", "τ/2"], "why": "Line-width: the spectrum of a decaying turning."}, {"q": "Sodium’s state lives 16.2 ns. About how wide is its line?", "a": "about 9.8 MHz", "w": ["about 9.8 Hz", "about 509 THz", "about 0.6 nm"], "why": "1/(2π × 16.2 ns)."}, {"q": "A state that lives longer gives what kind of line?", "a": "a narrower one", "w": ["a wider one", "a brighter one", "a bluer one"], "why": "32f’s squeeze, read in an atom."}, {"q": "A scanner’s signal is the transform of the proton density, read at γ̄Gt. Which technique?", "a": "place-as-frequency", "w": ["line-width", "transfer", "undo-transform"], "why": "A field with slope G gives each place its own pitch."}, {"q": "In a 1.5 T field, at what frequency do protons sing?", "a": "about 63.87 MHz", "w": ["about 42.58 MHz", "about 1.5 MHz", "about 425.8 Hz"], "why": "42.58 MHz for each tesla."}, {"q": "A signal is rebuilt from some of its coefficients. The energy of the miss is the energy of the dropped ones. Which technique?", "a": "dropped-energy", "w": ["energy-kept", "rounding-error", "fading-coefficients"], "why": "Energy-kept, on the difference."}, {"q": "Which k coefficients should be dropped to lose the least energy?", "a": "the k smallest", "w": ["the k fastest", "the k slowest", "any k"], "why": "Each dropped one costs its own |cₙ|²."}, {"q": "τy′ + y = f, with a daily swing of f. Which technique gives the inside swing?", "a": "thermal-lag", "w": ["line-width", "driven-response", "repeat-ahead"], "why": "The transfer technique at the daily frequency."}, {"q": "A house with τ = 5 h. About how late is the inside peak?", "a": "about 3.5 hours", "w": ["about 5 hours", "about 12 hours", "no delay"], "why": "52.6° of a 24-hour turn."}, {"q": "A crystal’s bright spot measures what?", "a": "the energy of one coefficient of its density", "w": ["the place of one atom", "the turn of one coefficient", "the whole density"], "why": "The turns are lost."}, {"q": "A perfect spectrometer shows a line of no width. Is the move allowed?", "a": "no: the width is fixed by the life", "w": ["yes: with fine enough slits", "yes: by line-width", "only for cold atoms"], "why": "The width belongs to the light."}];
/* phase F und_r32: understanding cards, appended (ids follow the deck's own) */
(window.LADDER_CARDS["32a"]=window.LADDER_CARDS["32a"]||[]).push(
 {"u":"32a1.1","q":"What is the nth turning, what does the right-angled-turnings technique say, and why does e^(ikx) total zero over [−π, π] for k ≠ 0?","a":"eₙ(x) = e^(inx); any two different turnings are at right angles and each has size 1; e^(ikx) goes a whole number of times round the circle, so its total over one repeat is 0","w":["eₙ(x) = e^(inx); any two turnings are at right angles, a turning with itself included; the total is 0 because e^(ikx) is odd","eₙ(x) = xⁿ; different turnings are at right angles and each has size 2π; the total is 0 because the weight is 1/2π","eₙ(x) = e^(inx); different turnings are at right angles only when n and m have different signs; the total is 0 only for even k"],"why":"⟨eₙ, eₘ⟩ is the average of e^(i(n − m)x)."},
 {"u":"32a2.1","q":"What are the nth coefficient and the Nth partial sum of f, and what changes and what stays when N grows?","a":"cₙ = ⟨f, eₙ⟩, the shadow of f on the nth turning, and S_N f = Σ cₙeₙ for n from −N to N, the closest such sum to f; a larger N adds terms and leaves every coefficient already found as it was","w":["cₙ = ⟨f, eₙ⟩ and S_N f sums n from −N to N; a larger N means every coefficient is found again to keep the sum closest","cₙ = f(n) and S_N f sums n from 0 to N; a larger N changes nothing","cₙ = ⟨f, eₙ⟩/‖f‖ and S_N f is any sum of 2N + 1 turnings; a larger N adds terms and keeps the old ones"],"why":"Right angles fix each shadow once."},
 {"u":"32a3.1","q":"Why do a real function’s coefficients come in flipped pairs, and what follows for even and odd functions?","a":"f is real, so the flip passes onto the turning and c₋ₙ is the flip of cₙ; the pair n, −n adds to aₙ cos nx + bₙ sin nx; an even function needs cosines alone and an odd one sines alone","w":["f is real, so c₋ₙ = cₙ; the pair adds to a cosine; even functions need sines alone and odd ones cosines alone","f is real, so every cₙ is real; the pair n, −n cancels; even and odd functions need both","f repeats, so c₋ₙ = −cₙ; the pair adds to a sine; an even function needs cosines alone and an odd one has no coefficients"],"why":"z plus its flip is twice the floor part."},
 {"u":"32a4.1","q":"Why is “adding the turning e_(N+1) changes the coefficients already found” a move to watch out for?","a":"the turnings are at right angles, so each coefficient is the shadow on its own turning and is fixed once found; a new turning adds a term and moves none","w":["the coefficients do change, but by less than ε","it holds for polynomials 1, x, x², … and so for turnings too","the new turning has size 0, so nothing can change"],"why":"That is the second half of the turning-shadow technique."});
(window.LADDER_CARDS["32b"]=window.LADDER_CARDS["32b"]||[]).push(
 {"u":"32b1.1","q":"What is the energy of f and of its nth turning, what does the fading-coefficients technique say, and where does the fading come from?","a":"‖f‖², the average of |f|² over one repeat, and |cₙ|²; the turnings’ energies add up to at most ‖f‖², so cₙ heads to 0 as n grows either way; the terms of a sum that stays under a bound must head to 0","w":["‖f‖ and |cₙ|; the energies add up to exactly ‖f‖ by the bound alone; the fading comes from the weight 1/2π","‖f‖² and |cₙ|²; the energies add up to at most ‖f‖², so Σ cₙ settles; the fading comes from f being continuous","the largest value of |f|² and cₙ²; each energy is at most ‖f‖², so cₙ stays bounded; nothing fades"],"why":"It is the energy bound of 31h2 said about a wave."},
 {"u":"32b2.1","q":"What does the turnings-near-everything technique say, and how does its proof get from a polynomial to a sum of turnings?","a":"every continuous f that repeats every 2π has a finite sum of turnings within ε of it at every x at once; an even g is h(cos x) with h continuous on [−1, 1], a polynomial p is near h, and p(cos x) is a sum of turnings","w":["every f of finite energy has a finite sum of turnings within ε at every x; a polynomial p near f is itself a sum of turnings","every continuous repeating f has S_N f within ε at every x once N is large; a polynomial in x is bent by x = e^(iθ)","every continuous repeating f has a finite sum of turnings near it in size only; an even g is p(sin x) for a polynomial p"],"why":"One bend of the input carries 31j2’s polynomials to turnings."},
 {"u":"32b3.1","q":"What does the energy-kept technique say, and why does the nearness of 32b2 turn the energy bound into an equality?","a":"for every repeating f of finite energy, S_N f heads to f in size and ‖f‖² = Σ |cₙ|²; finite sums of turnings come as near as you like to f, S_N f is the closest of them, so the leftover ‖f − S_N f‖² heads to 0","w":["for every continuous f, S_N f(x) heads to f(x) at every x and ‖f‖² = Σ |cₙ|²; the leftover is 0 for some finite N","for every repeating f of finite energy, ‖f‖² ≥ Σ |cₙ|² with equality only for finite sums of turnings","for every repeating f of finite energy, ‖f‖ = Σ |cₙ|; nearness at every x gives nearness of the coefficients one by one"],"why":"‖f‖² = Σ over |n| ≤ N of |cₙ|² + ‖f − S_N f‖²."},
 {"u":"32b4.1","q":"Which wave gives the total of 1 + ¼ + ⅑ + ⋯, what are its coefficients, and how does the energy-kept technique give π²/6?","a":"the sawtooth, x on (−π, π) repeated, with cₙ = i(−1)ⁿ/n and c₀ = 0; its energy is π²/3 and the energies of its turnings add to 2 Σ 1/n², so Σ 1/n² = π²/6","w":["the square wave, with cₙ = 1/n²; its coefficients add to π²/6","the sawtooth, with cₙ = i(−1)ⁿ/n; setting x = π in its series gives Σ 1/n² = π²/6","the sawtooth, with cₙ = 1/n; its energy is π²/6 and the turnings’ energies add to Σ 1/n"],"why":"Both n and −n carry 1/n², hence the 2."},
 {"u":"32b5.1","q":"Why is “S_N f heads to f in size, so S_N f(x) heads to f(x) at every x” a move to watch out for?","a":"nearness in size is nearness of an average, and an average allows misses at points; settling at a point is another question, taken up in 32c","w":["nearness in size is stronger than nearness at every point, so the claim is too weak","it fails only because the weight 1/2π was left out","S_N f never comes near f in size unless f is a finite sum of turnings"],"why":"31g5 already kept settling in size apart from settling at points."});
(window.LADDER_CARDS["32c"]=window.LADDER_CARDS["32c"]||[]).push(
 {"u":"32c1.1","q":"What does the turning-kernel technique say S_N f(x) is, and why does D_N have average 1?","a":"the average of f(x − s) over one repeat, weighted by D_N(s) = sin((N + ½)s)/sin(s/2); D_N is the sum of the turnings from −N to N, and only the turning n = 0 has a total","w":["the average of f(x − s) weighted by D_N(s) = sin(Ns)/s; D_N has average 1 because it is never negative","the value f(x) times D_N(x); D_N has average 1 because it is 2N + 1 at s = 0","the average of f(x − s) weighted by D_N(s) = sin((N + ½)s)/sin(s/2); D_N has average 1 because each turning has average 1"],"why":"D_N swings below 0; its average is 1 all the same."},
 {"u":"32c2.1","q":"What does the slope-returns technique say, and where does its proof use the slope and where fading?","a":"if f repeats, is sized and bounded and has a slope at x, then S_N f(x) settles at f(x); the slope keeps (f(x − s) − f(x))/sin(s/2) bounded near s = 0, and the leftover is then two coefficients of a function of finite energy, which fade","w":["if f is continuous at x then S_N f(x) settles at f(x); the slope is not used, and fading makes D_N head to 0","if f has a slope at x then S_N f comes near f everywhere at once; the slope bounds D_N and fading bounds f","if f has a slope at x then S_N f(x) settles at f′(x); the slope gives the limit and fading is not used"],"why":"A bound C|s| near x is enough; continuity alone is not."},
 {"u":"32c3.1","q":"What does the halfway technique say, and why does the value of f at the jump itself not matter?","a":"at a jump with a slope from each side the partial sums settle at (f(x⁻) + f(x⁺))/2; the sum is made of totals, and a total does not see one point","w":["the partial sums settle at f(x), whichever value f is given there","the partial sums settle at f(x⁺), the value from the right; the value at the jump is used as a start","the partial sums do not settle at a jump at all; the value at the jump is the only one that matters"],"why":"D_N is even, so each side gets half the weight."},
 {"u":"32c4.1","q":"What does the lasting-overshoot technique say, and how can the sums still settle at every fixed x?","a":"beside each jump of the square wave the partial sums peak near 1.179 however many turnings are used; the peak sits at π/(2M), moving toward the jump and narrowing, so it passes every fixed x","w":["the peak beside a jump shrinks toward 1 as turnings are added, so the sums settle everywhere at once","the peak stays near 1.179 at one fixed x, so the sums do not settle there","the peak grows without bound as turnings are added, and the sums settle only at the jump"],"why":"About nine per cent of the jump, at every M."},
 {"u":"32c5.1","q":"Why is “more turnings make the overshoot beside a jump smaller” a move to watch out for?","a":"more turnings make the peak narrower and closer to the jump, never lower: it stays near 1.179 at every M","w":["more turnings make the peak higher without bound","the overshoot is a rounding error of the picture, and the sums never pass 1","more turnings do lower the peak, only slowly, like 1/M"],"why":"A limit everywhere at once of continuous sums would be continuous, and the square wave jumps."});
(window.LADDER_CARDS["32d"]=window.LADDER_CARDS["32d"]||[]).push(
 {"u":"32d1.1","q":"What is the blend f * g, what does the blend-coefficients technique say, and what does a blend do to one turning?","a":"(f * g)(x) is the average of f(x − t) g(t) over one repeat, an average of f near x weighted by g; cₙ(f * g) = cₙ(f) cₙ(g); the turning eₙ comes out as cₙ(g) eₙ, the same turning scaled","w":["(f * g)(x) = f(x) g(x); cₙ(f * g) = cₙ(f) cₙ(g); a turning comes out at another speed","(f * g)(x) is the average of f(x − t) g(t); cₙ(f * g) = cₙ(f) + cₙ(g); a turning comes out shifted","(f * g)(x) is the average of f(t) g(t); cₙ(f * g) = cₙ(f) cₙ(g) only for n = 0; a turning is wiped out"],"why":"Every turning is a vector the blend only stretches."},
 {"u":"32d2.1","q":"What does the blend-smooths technique say, and whose smoothness does the blend take on?","a":"if g has a continuous slope then f * g has a slope for every sized bounded f, and (f * g)′ = f * g′; the blend takes on the smoothness of the smoother, since the slope can be put on g alone","w":["if f and g both have slopes then (f * g)′ = f′ * g′; the blend is as rough as the rougher","if g has a continuous slope then (f * g)′ = f′ * g, so f needs a slope too","if g is bounded then f * g has a slope; the smoothness comes from the weight 1/2π"],"why":"Slide the variable so x sits inside g only."},
 {"u":"32d3.1","q":"What are the averages σ_N f, what does the averaged-sums technique say, and what does F_N have that D_N lacks?","a":"σ_N f = (S₀f + ⋯ + S_(N−1)f)/N = f * F_N; for continuous repeating f they come near f everywhere at once; F_N is never negative, so with average 1 it is a true averaging weight and gives no overshoot","w":["σ_N f = S_N f/N; they come near f in size only; F_N has average 1 and D_N does not","σ_N f = (S₀f + ⋯ + S_(N−1)f)/N; they come near every sized f at every x; F_N is even and D_N is not","σ_N f = f * D_N; they settle at f(x) where f has a slope; F_N is bounded and D_N is not"],"why":"F_N is a square over N."},
 {"u":"32d4.1","q":"Why is “the coefficients of fg are the products of the coefficients of f and g” a move to watch out for?","a":"the product of two functions is not their blend; it is the blend f * g whose coefficients are cₙ(f) cₙ(g)","w":["the coefficients of fg are the sums cₙ(f) + cₙ(g)","it holds once f and g are both continuous","the product fg has no coefficients"],"why":"Try f = g = e₁: fg = e₂, whose first coefficient is 0, not 1."});
(window.LADDER_CARDS["32e"]=window.LADDER_CARDS["32e"]||[]).push(
 {"u":"32e1.1","q":"What is the transform of f, how do 32a’s coefficients become it, and what does the transform-bound technique say?","a":"f̂(ξ) = ∫ f(x) e^(−2πixξ) dx over the line; cut f to [−L, L] and repeat it every 2L, and its coefficients are f̂(n/(2L))/(2L), at frequencies that fill the line as L grows; if f has a finite total size, f̂ is bounded by that total and continuous","w":["f̂(ξ) = ∫ f(x) e^(−2πixξ) dx; the coefficients become it by letting N grow; f̂ then has a finite total size too","f̂(ξ) = Σ cₙ e^(inξ); the coefficients are its values at whole ξ; f̂ is bounded by the energy of f","f̂(ξ) = ∫ f(x) e^(−2πixξ) dx; as L grows the frequencies n/(2L) spread apart; f̂ is bounded but may jump"],"why":"The fenced-limit technique, with fence |f|."},
 {"u":"32e2.1","q":"What does the own-transform technique say, and which rate statement and start settle it?","a":"the bell e^(−πx²) has transform e^(−πξ²); the transform obeys y′ = −2πξy with y(0) = 1, the bell obeys the same technique and start, and a rate statement with a start has one solution","w":["every bell e^(−cx²) is its own transform; it obeys y′ = y with y(0) = 1","the bell e^(−πx²) has transform 1; it obeys y′ = 0 with y(0) = 1","the bell e^(−πx²) has transform e^(−πξ²), found by reading the total off a picture; no rate statement is used"],"why":"y(0) = 1 is the bell total of 30j1."},
 {"u":"32e3.1","q":"What does the undo-transform technique say, why does its proof put a bell inside the total, and what happens to the bell?","a":"if f and f̂ both have finite total sizes then f(x) = ∫ f̂(ξ) e^(2πixξ) dξ wherever f is continuous; the bell tames the total so the two orders agree and turns it into an average of f near x by a never-negative weight; then ε heads to 0 and the bell is let go","w":["if f has a finite total size then f(x) = ∫ f̂(ξ) e^(2πixξ) dξ at every x; the bell is put in because f is a bell, and it stays","if f and f̂ have finite total sizes then f(x) = ∫ f̂(ξ) e^(−2πixξ) dξ; the bell makes f̂ continuous and is kept as a weight","if f and f̂ have finite total sizes then f = f̂; the bell is its own transform, which is the whole proof"],"why":"A signal and its transform carry the same information."},
 {"u":"32e4.1","q":"What does the transform-energy technique say, and which function h does the proof build?","a":"if f has a finite total size and a finite energy, then ∫|f̂|² = ∫|f|²; h = f * f̃ with f̃(x) the flip of f(−x), so ĥ = |f̂|² and h(0) = ∫|f|²","w":["∫|f̂| = ∫|f|; h = f + f̃ with ĥ = 2f̂","∫|f̂|² ≤ ∫|f|², with equality only for bells; h = f · f̃ with ĥ = |f̂|²","∫|f̂|² = ∫|f|²; h = f * f with ĥ = f̂²"],"why":"The transform of a blend is the product of the transforms."},
 {"u":"32e5.1","q":"Why is “f has a finite total size, so its transform does too” a move to watch out for?","a":"the box that is 1 on [−½, ½] has a finite total, and its transform sin(πξ)/(πξ) fades only like 1/ξ and does not","w":["the bell has a finite total and its transform does not","a transform never has a finite total size","the claim fails only for functions that repeat"],"why":"That is why the undo-transform technique asks it of both."});
(window.LADDER_CARDS["32f"]=window.LADDER_CARDS["32f"]||[]).push(
 {"u":"32f1.1","q":"What does the slope-to-frequency technique say, and why do the end terms of the parts line vanish?","a":"if f and f′ have finite total sizes, the transform of f′ is 2πiξ times f̂; f(L) settles as L grows since ∫|f′| is finite, and its limit must be 0 or ∫|f| would be endless","w":["the transform of f′ is the slope of f̂; the end terms vanish because the turning has size 0 far out","the transform of f′ is 2πiξ times f̂; the end terms vanish because f repeats","the transform of f′ is f̂/(2πiξ); the end terms vanish because f is even"],"why":"A slope in x becomes a multiple in ξ."},
 {"u":"32f2.1","q":"What are the two widths of a signal of energy 1, what does the spread-product technique say, and which bound does its proof spend?","a":"Δx = √(∫x²|f|² dx) and Δξ = √(∫ξ²|f̂|² dξ), each density centred at 0; Δx · Δξ ≥ 1/(4π) whenever xf and f′ have finite energy; the proof spends the product bound of 31a3 on xf and f′","w":["Δx and Δξ are the lengths of the intervals where f and f̂ are not 0; Δx · Δξ ≥ 1; the proof spends the energy bound of 31h2","Δx = √(∫x²|f|² dx) and Δξ = √(∫ξ²|f̂|² dξ); Δx · Δξ ≤ 1/(4π); the proof spends the product bound","Δx = ∫|x||f| dx and Δξ = ∫|ξ||f̂| dξ; Δx + Δξ ≥ 1/(4π); the proof spends the three-sided bound"],"why":"The width of f′ is 2π times the frequency width, by 32f1 and 32e4."},
 {"u":"32f3.1","q":"What does the tightest-bell technique say, and which rate statement does equality force?","a":"the product of the widths is exactly 1/(4π) only for bells, the multiples of e^(−cx²) with c > 0; equality in the product bound makes f′ = −λxf with λ real and positive, whose solutions are A e^(−λx²/2)","w":["the product is exactly 1/(4π) for every even signal; equality forces f′ = −λf, whose solutions are A e^(−λx)","the product is exactly 1/(4π) only for boxes; equality forces f′ = 0","the product is never exactly 1/(4π); the bells only come near it"],"why":"Equality in 31a3 means one is a multiple of the other."},
 {"u":"32f4.1","q":"Why is “a better instrument can beat the width product of 1/(4π)” a move to watch out for?","a":"the bound is about the signal, its width in time and the width of its own transform; no instrument enters the proof, so none can beat it","w":["the bound is about today’s instruments and falls as they improve","a better instrument does beat it, for bells only","the bound is 1, and instruments already beat 1/(4π)"],"why":"It is the product bound said about xf and f′."});
(window.LADDER_CARDS["32g"]=window.LADDER_CARDS["32g"]||[]).push(
 {"u":"32g1.1","q":"What does it mean for a signal to have no frequency above B, and why do its samples at the spacing 1/(2B) fix it?","a":"f is a total of F(ξ) e^(2πixξ) over [−B, B] alone, so its transform is 0 outside; the samples f(k/(2B)) are, up to the factor 2B, the coefficients of F on [−B, B], coefficients fix F, and F fixes f","w":["f never changes faster than B per unit; the samples fix f because a straight line joins each pair","the transform of f is 0 inside [−B, B]; the samples are the values of F at whole ξ","f is a total of F over [−B, B]; the samples at the spacing 1/B are the coefficients of F, and any spacing under 1/B would do as well"],"why":"The energy-kept technique fixes a function by its coefficients."},
 {"u":"32g2.1","q":"What does the sample-rebuild technique say, and why does the sum pass through every sample?","a":"f(x) = Σ f(k/(2B)) sinc(2Bx − k) over every whole k; at x = k/(2B) the kth sinc is 1 and every other is 0, since sinc is 1 at 0 and 0 at every other whole number","w":["f(x) is the straight line between the two nearest samples; it passes through them by its making","f(x) = Σ f(k/(2B)) sinc(2Bx − k) over the nearest two k; the other samples have no say between instants","f(x) = Σ f(k/(2B)) e^(2πikx); every term is 1 at a sample instant"],"why":"Between the instants every sample has its say."},
 {"u":"32g3.1","q":"What does the same-samples technique say, and why must a sound be filtered before it is sampled?","a":"at the rate r the turnings of frequencies ξ and ξ + r give the same samples, so a frequency above r/2 is read as one between −r/2 and r/2; whatever lies above r/2 must be cut first, or it comes back as a tone that was never there","w":["at the rate r the frequencies ξ and 2ξ give the same samples; the filter is there to make the sound louder","at the rate r a frequency above r/2 gives samples that are all 0, so it is lost; the filter saves storage","at the rate r the frequencies ξ and ξ + r give the same samples; so no frequency at all can be told from the samples, filtered or not"],"why":"30 000 Hz at 44 100 a second is read as 14 100 Hz."},
 {"u":"32g4.1","q":"Why is “sampling at the rate B is enough for a signal with no frequency above B” a move to watch out for?","a":"the spacing must be 1/(2B), a rate of twice the top frequency; at the rate B the frequencies above B/2 are read in disguise","w":["no rate is enough for any signal","the rate must be B², since energy goes as the square","the rate B is enough once the signal is filtered after sampling"],"why":"The transform lives on [−B, B], a repeat of length 2B."});
(window.LADDER_CARDS["32h"]=window.LADDER_CARDS["32h"]||[]).push(
 {"u":"32h1.1","q":"What does the square-recipe technique say, and which two endless sums are read off it?","a":"q(x) = (4/π)(sin x + sin 3x/3 + sin 5x/5 + ⋯), odd speeds alone; at x = π/2 the slope-returns technique gives 1 − 1/3 + 1/5 − ⋯ = π/4, and the energy-kept technique gives 1 + 1/9 + 1/25 + ⋯ = π²/8","w":["q(x) = (4/π)(sin x + sin 2x/2 + sin 3x/3 + ⋯); at x = π/2 it gives 1 + 1/2 + 1/3 + ⋯ = π/4","q(x) = (4/π)(cos x + cos 3x/3 + ⋯); the energy-kept technique gives 1 − 1/3 + 1/5 − ⋯ = π/4 and the value at 0 gives π²/8","q(x) = (4/π)(sin x + sin 3x/9 + sin 5x/25 + ⋯); both sums come from the value at x = π/2"],"why":"A value at a point needs 32c; an energy needs 32b."},
 {"u":"32h2.1","q":"What do a slide, a stretch and an added constant each do to a wave’s coefficients?","a":"a slide by s multiplies cₙ by e^(−ins); a repeat of length T in place of 2π keeps every coefficient, with the turning e^(2πint/T) in place of e^(inx); a constant changes c₀ alone","w":["a slide adds s to every cₙ; a stretch divides cₙ by T; a constant changes every cₙ","a slide multiplies cₙ by e^(−ins); a stretch moves cₙ to c_(nT); a constant multiplies c₀","a slide changes nothing; a stretch keeps every coefficient; a constant changes c₀ and c₁"],"why":"So one total serves every sawtooth."},
 {"u":"32h3.1","q":"What does the corner-and-jump technique say, and how does it give the triangle’s recipe from the square’s?","a":"for a continuous repeating f with a sized bounded slope, cₙ(f′) = in cₙ(f); so a jump gives coefficients falling like 1/n and corners without a jump like 1/n²; the triangle’s slope is the square wave, so cₙ(w) = cₙ(q)/(in), with c₀ the average of |x|","w":["cₙ(f′) = cₙ(f)/(in); a jump gives 1/n² and a corner 1/n; the triangle’s coefficients are in times the square’s","cₙ(f′) = in cₙ(f) for every sized f, jumps included; the triangle and the square have the same coefficients","cₙ(f′) = n² cₙ(f); a jump gives 1/n and a corner 1/n³; the triangle’s recipe is found by squaring the square’s"],"why":"Each further continuous slope buys one more power of n."},
 {"u":"32h4.1","q":"Why is “sliding a wave changes the sizes of its coefficients” a move to watch out for?","a":"a slide multiplies each coefficient by the turn e^(−ins), which has size 1; the sizes |cₙ| stay, only the turns change","w":["a slide leaves every coefficient exactly as it was","a slide changes the sizes but keeps their sum","a slide changes c₀ alone"],"why":"So a slide keeps the energy at every speed."});
(window.LADDER_CARDS["32i"]=window.LADDER_CARDS["32i"]||[]).push(
 {"u":"32i1.1","q":"What is the blend of two lists, and what does the list-blend technique say about polynomials and about chances of sums?","a":"its kth entry is a₀b_k + a₁b_(k−1) + ⋯ + a_kb₀, every pairing whose places add to k; the coefficients of a product of polynomials are the blend of their lists, so the chance list of a sum of two independent whole-number counts is the blend of their chance lists","w":["its kth entry is a_kb_k; the coefficients of a product are the products of the coefficients, so P(X + Y = k) = P(X = k) P(Y = k)","its kth entry is a_k + b_k; the coefficients of a sum of polynomials add, so the chances of a sum add","its kth entry is a₀b_k + ⋯ + a_kb₀; this gives the chances of a sum of any two counts, independent or not"],"why":"Two dice make the tent 1, 2, …, 6, …, 2, 1 over 36."},
 {"u":"32i2.1","q":"What does the gain-per-turning technique say, and what do the size and the turn of H(n) each do?","a":"a blend with g multiplies each turning eₙ by its own number H(n) = cₙ(g); the size |H(n)| is the gain at that speed and the turn of H(n) slides the turning","w":["a blend multiplies every turning by the same number H; its size is the gain and its turn changes the speed","a blend adds H(n) to each turning; the size is the shift and the turn is the gain","a blend multiplies eₙ by H(n) = cₙ(g); the size |H(n)| changes the speed and the turn of H(n) is the gain"],"why":"The window average has real H(n) = sin(nh)/(nh): it shifts nothing."},
 {"u":"32i3.1","q":"What does the stepped-filter technique say, and why is the running filter a blend?","a":"yₖ = (1 − β)y_(k−1) + βxₖ sends e^(iωk) to H(ω)e^(iωk) with H(ω) = β/(1 − (1 − β)e^(−iω)); unrolled, yₖ = β Σ (1 − β)ʲ x_(k−j), a blend of the readings with the list β(1 − β)ʲ","w":["it sends e^(iωk) to a turning of speed (1 − β)ω; it is a blend with the list (β, 1 − β) and nothing else","it sends e^(iωk) to H(ω)e^(iωk) with H(ω) = β; unrolled, it is the plain average of the last 1/β readings","it sends e^(iωk) to H(ω)e^(iωk) with H(ω) = β/(1 − (1 − β)e^(−iω)); it is not a blend, since it uses its own old output"],"why":"A geometric sum of size 1 − β < 1."},
 {"u":"32i4.1","q":"Why is “a filter can turn one speed into another” a move to watch out for, for a blend?","a":"a blend sends each turning to a multiple of itself: it can scale it, slide it or wipe it out, and never make a speed that was not in the input","w":["a blend doubles every speed","a blend turns high speeds into low ones, which is how it smooths","a blend leaves every turning exactly as it was"],"why":"Every turning is a vector the blend only stretches (32d1)."});
(window.LADDER_CARDS["32j"]=window.LADDER_CARDS["32j"]||[]).push(
 {"u":"32j1.1","q":"What does the rate-to-algebra technique say, when can the division fail, and what does that mean for the spring?","a":"a repeating solution of y″ + by′ + cy = f has cₙ(y) = cₙ(f)/(c − n² + ibn), so there is exactly one when no bottom is 0; the bottom is 0 only for b = 0 and c = n², a spring with no brake whose own speed is a speed of the push, and then that speed must be absent from the push","w":["cₙ(y) = cₙ(f)/(c + n² + bn); the division fails whenever b = 0; the spring then stands still","cₙ(y) = cₙ(f)(c − n² + ibn); nothing can fail; every solution repeats","cₙ(y) = cₙ(f)/(c − n² + ibn); the division fails for every n above √c; the spring then has two repeating solutions"],"why":"A slope is in, two slopes −n²."},
 {"u":"32j2.1","q":"What does the driven-response technique say, and why does a square push ring a spring tuned near speed 3 mostly at speed 3?","a":"each speed n of the push is scaled by 1/√((ω₀² − n²)² + 4β²n²), most near ω₀; the square push’s third speed holds a third of its first, but its divisor near ω₀ is tiny, so it comes out about eight times the first","w":["the spring answers only the push’s largest speed, n = 1; speed 3 rings because 3 is odd","each speed is scaled by 1/n²; speed 3 rings because the square push holds most of its amount there","each speed is scaled by √((ω₀² − n²)² + 4β²n²); speed 3 rings because it is multiplied by the largest number"],"why":"0.424/√(0.12² + 0.09) ≈ 1.31 against 0.157."},
 {"u":"32j3.1","q":"What does the transfer technique say, what is the transfer function, and what does the example circuit pass and cut?","a":"for y′ + ky = f with k > 0, ŷ(ξ) = f̂(ξ)/(k + 2πiξ); H(ξ) = 1/(k + 2πiξ) is the gain-per-turning number for every frequency at once; the resistor and capacitor pass low tones (0.954 at 50 Hz) and cut high ones (0.157 at 1000 Hz)","w":["ŷ(ξ) = f̂(ξ)(k + 2πiξ); H is the slope of f̂; the circuit passes high tones and cuts low ones","ŷ(ξ) = f̂(ξ)/(k + 2πiξ) for every k, negative too; H is the same number at every frequency; the circuit passes all tones alike","ŷ(ξ) = f̂(ξ) − k; H is the transform of y; the circuit cuts one frequency, 1000 Hz, and passes the rest"],"why":"The slope-to-frequency technique turns y′ into 2πiξ ŷ."},
 {"u":"32j4.1","q":"Why is “the spring swings most at the push’s largest speed” a move to watch out for?","a":"each speed of the push is divided by its own number, and that number is small near the spring’s own speed; a small speed of the push next to ω₀ can come out the loudest","w":["the spring swings equally at every speed of the push","the spring swings only at its own speed, whatever the push","the spring swings most at the push’s highest speed"],"why":"The answer is the push’s amount over the divisor, speed by speed."});
(window.LADDER_CARDS["32k"]=window.LADDER_CARDS["32k"]||[]).push(
 {"u":"32k1.1","q":"What is the stepped transform of N samples, what does the sampled-turnings technique say, and which sum makes the turnings at right angles?","a":"X_k = Σ x_j ω^(−jk) with ω = e^(2πi/N); the N stepped turnings are at right angles, so x_j = (1/N) Σ X_k ω^(jk); the geometric sum Σ ω^(j(k − m)) is 0 unless k − m is a multiple of N, and then it is N","w":["X_k = Σ x_j ω^(−jk); the list is rebuilt by x_j = Σ X_k ω^(jk) with no factor; the sum Σ ω^j is always 1","X_k = x_k ω^(−k); the turnings are at right angles because ω has size 1","X_k = Σ x_j ω^(−jk) with ω = e^(2πi/N); the turnings are at right angles only when N is a power of 2"],"why":"(1, 2, 3, 4) has X = (10, −2 + 2i, −2, −2 − 2i)."},
 {"u":"32k2.1","q":"What does the halving-transform technique say, why does the second half reuse E and O, and what does that do to the cost?","a":"X_k = E_k + ω^(−k)O_k and X_(k+M) = E_k − ω^(−k)O_k; E and O repeat every M and ω^M = −1, so only a sign changes; two half transforms and N more steps give about N log₂ N steps in place of N²","w":["X_k = E_k + O_k and X_(k+M) = E_k − O_k; E and O are found again for the second half; the cost stays N²","X_k = E_k + ω^(−k)O_k and X_(k+M) = E_k − ω^(−k)O_k; the cost halves, to N²/2","X_k = E_k · O_k; E and O are reused because the list is even; the cost falls to N"],"why":"T(N) = 2T(N/2) + N."},
 {"u":"32k3.1","q":"Why must music be sampled more than 40 000 times a second, why is the rate set above that, and what set the exact number?","a":"hearing reaches about 20 000 Hz and the rate must pass twice the top frequency; the filter that cuts what lies above half the rate needs a band to fall over, from 20 000 to 22 050 Hz; 44 100 was fixed by storing sound on video tape, three samples to a usable line in both video systems","w":["hearing reaches 40 000 Hz; the rate is set above it for loudness; 44 100 is the nearest power of 2","the rate must pass twice 20 000 Hz; it is set above 40 000 because no filter is needed then; 44 100 was chosen at random","the rate must equal the top frequency; 44 100 Hz is the measured top of hearing"],"why":"Part technique, part history."},
 {"u":"32k4.1","q":"Why is “the halving way gives a different answer from the plain way” a move to watch out for?","a":"the halving way adds the same sums, grouped into even and odd places; the answer is the same and only the cost changes","w":["the halving way is an estimate that is close for large N","the halving way gives the transform of half the list","the two agree only for N = 4"],"why":"X₁ = −2 + 2i for (1, 2, 3, 4) either way."});
(window.LADDER_CARDS["32l"]=window.LADDER_CARDS["32l"]||[]).push(
 {"u":"32l1.1","q":"What is a level point of the phase, what does the no-level-point technique say, and which move gives the 1/λ?","a":"an x where φ′(x) = 0; with none on [u, v], |I(λ)| ≤ C/λ with C fixed by g and φ; write e^(iλφ) as its own slope over iλφ′ and take parts, which is allowed since φ′ is never 0","w":["an x where φ(x) = 0; with none, I(λ) = 0; the move is the bound |e^(iλφ)| = 1","an x where φ′(x) = 0; with none, |I(λ)| ≤ C/√λ; the move is the turning-bell total","an x where g(x) = 0; with none, |I(λ)| ≤ C/λ; the move is dividing by g"],"why":"Each further round of parts, when the ends go, buys another 1/λ."},
 {"u":"32l2.1","q":"What does the turning-bell technique say, which loop does its proof use, and why does the curved side fade?","a":"the total of e^(iλx²) over the line settles at √(π/λ) e^(iπ/4), by cancelling alone; the loop is the wedge from 0 to R to Re^(iπ/4) and back; on the arc |e^(iz²)| = e^(−R² sin 2θ), so the arc’s total is under π/(4R)","w":["the total settles at √(π/λ), with no turn; the loop is a full circle; the arc fades because its length shrinks","the total settles absolutely at √(π/λ) e^(iπ/4); the loop is a rectangle; the far side fades because e^(iz²) has size 1","the total does not settle; the wedge shows the arc’s total grows like R"],"why":"Along the slanted side iz² = −t², the bell of 30j1."},
 {"u":"32l3.1","q":"What does the level-point technique say, and why does the part near a level point shrink only like 1/√λ?","a":"with one level point x₀ and φ″(x₀) ≠ 0, I(λ) is about g(x₀) e^(iλφ(x₀)) √(2π/(λ|φ″(x₀)|)) e^(±iπ/4); near x₀ the phase is about a square, so the turning-bell total gives 1/√λ, while the pieces with no level point give 1/λ, which is smaller","w":["I(λ) is about g(x₀)/λ; near x₀ the phase is about a line, so parts give 1/λ everywhere","I(λ) is about g(x₀) e^(iλφ(x₀)) √(2π/(λ|φ″(x₀)|)), and the turn e^(±iπ/4) can be left out; near x₀ the total does not shrink at all","I(λ) is about the average of g; every part of the interval counts the same"],"why":"Where the phase pauses, the turning does not cancel."},
 {"u":"32l4.1","q":"Why is “the total of e^(ix²) out to forever settles absolutely” a move to watch out for?","a":"every value of e^(ix²) has size 1, so the total of the sizes is endless; the total settles by cancelling alone","w":["e^(ix²) fades like a bell, so it does settle absolutely","the total does not settle in any way","it settles absolutely once λ is large"],"why":"The sizes total the length of the line."});
(window.LADDER_CARDS["32·then"]=window.LADDER_CARDS["32·then"]||[]).push(
 {"u":"32·then.1.1","q":"What does the line-width technique say, and why is a line from a longer-lived state narrower?","a":"a turning of frequency ν₀ whose strength dies over a life τ has a spectrum peaked at ν₀ with width 1/(2πτ) at half height; a longer τ is a longer signal in time, so a narrower one in frequency","w":["its spectrum is one sharp line at ν₀ of no width; the life changes only the brightness","its spectrum has width 2πτ; a longer life gives a wider line","its spectrum is peaked at 1/τ; a longer life moves the line to a lower frequency"],"why":"32f’s squeeze, read in an atom."},
 {"u":"32·then.2.1","q":"What does the place-as-frequency technique say, and why does undoing the transform give a picture?","a":"in a field with slope G each place x turns at its own frequency, so the signal at time t, with the common frequency turned back, is the transform of the proton density at the frequency γ̄Gt; the undo-transform technique then returns the density, place by place","w":["the scanner takes a photograph of the protons; the transform is used only to store it","the signal at time t is the density at the place x = t; no transform is needed","each place turns at the same frequency, and the signal’s size gives the total of the density only"],"why":"425.8 Hz for every millimetre at 10 mT per metre."},
 {"u":"32·then.3.1","q":"What does the dropped-energy technique say, and which coefficients should be dropped?","a":"a signal rebuilt from some of its coefficients differs from the whole by exactly the sum of the energies of the dropped ones; so drop the smallest","w":["the difference has energy in proportion to how many coefficients were dropped; so drop any","the difference has energy equal to the largest dropped coefficient; so drop the highest speeds, whatever their size","the difference has no energy as long as c₀ is kept"],"why":"The energy-kept technique, for the difference."},
 {"u":"32·then.4.1","q":"What does the thermal-lag technique say, and why is a house with a longer τ both cooler at its peak and later?","a":"a swing of period P reaches the inside scaled by 1/√(1 + (2πτ/P)²) and late by the turn whose tangent is 2πτ/P; a longer τ makes 2πτ/P larger, which shrinks the scale and grows the turn","w":["the swing reaches the inside unscaled and late by τ; a longer τ only delays","the swing is scaled by 1/(1 + τ) and is not late; a longer τ lowers the average too","the swing is scaled by √(1 + (2πτ/P)²); a longer τ makes the inside swing wider"],"why":"It is the transfer function of 32j3 at one frequency."},
 {"u":"32·then.5.1","q":"What does each bright spot of a crystal measure, and what does a photograph of the spots fail to hold?","a":"the energy |cₙ|² of one coefficient of the crystal’s repeating density; the photograph does not hold the turn of each cₙ, and without the turns the density cannot be rebuilt","w":["the place of one atom; the photograph fails to hold the atoms’ colours","the coefficient cₙ itself, size and turn; nothing is missing","the average density of the crystal; the photograph fails to hold c₀"],"why":"A spot is a share, as in 32b."},
 {"u":"32·then.6.1","q":"Why is “a perfect spectrometer would show a spectral line of no width” a move to watch out for?","a":"the width 1/(2πτ) belongs to the light itself, fixed by the life of the state; a signal that dies away cannot be one pure frequency","w":["the width comes from the slits and falls to 0 as they improve","a line of no width would need endless brightness, which is the only bar","the width is the gap between sodium’s two lines"],"why":"The bound is about the signal, not the instrument (32f4)."});
